package org.apache.commons.lang.text;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_59_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadRight("test", 10, '*');
        String expected = "test******"; // "test" + 6 '*' characters to make the total length 10
        assertEquals("The string should be padded to a total length of 10 with '*' characters.", expected, sb.toString());
    }
}

